echo '' | base64 -d > /tmp/corners.zip
rm -rf /tmp/corners; mkdir -p /tmp/corners; unzip -oq /tmp/corners.zip -d /tmp/corners
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/corners; rm -rf $D; mkdir -p $D; cd $D
cp /tmp/corners/*.v /tmp/corners/*.tcl $D/
for t in p_cy1 p_cynet f_fdre_bff f_ldce_bff c_ce_lut r_ram_wepin r_ram_we1; do /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1; if grep -q "DONE_$t" $t.log; then echo "OK $t"; else echo "FAIL $t"; grep -m2 -E "^ERROR|missing|invalid" $t.log; fi; done
tar czf /tmp/corners_out.tgz *.bit 2>/dev/null || echo NOTAR
echo CORNERSDONE
